custom_css:
/* --- 冰岛微风 (Icelandic Breeze) 黑白极简主题 感谢代码楼里老师们的代码https://discord.com/channels/1291925535324110879/1380392618336194702
感谢尾老师，类名，输入框伪提示词来自尾老师，hy老师的去除思维链箭头，na老师的悬浮底栏和思维链文字自定义，楼层信息自定义，12的去思维链背景色。感谢NA老师的去阴影，感谢咩野老师的去除全局阴影. - *--- */

/* --- 1. 字体导入 --- */
@import url('https://fonts.googleapis.com/css2?family=Great+Vibes&display=swap');
@import url("https://fontsapi.zeoseven.com/796/main/result.css");
@import url("https://fontsapi.zeoseven.com/253/main/result.css");

@font-face {
    font-family: 'Haishui';
    src: url('https://cdn.jsdelivr.net/gh/loud23for-ship-it/ziti@main/haishui.woff2') format('woff2');
    font-weight: normal;
    font-style: normal;
    font-display: swap;
}

@font-face {
    font-family: 'LingDong';
    src: url('https://cdn.jsdelivr.net/gh/loud23for-ship-it/ziti@main/lingdong.woff2') format('woff2');
    font-weight: normal;
    font-style: normal;
}

/* --- 2. 核心颜色与样式变量 --- */
:root {
    --theme-bg: #EAEAEA;
    --panel-bg-color: rgba(245, 245, 245, 0.85);
    --panel-bg-hover: rgba(230, 230, 230, 0.95);
    --card-bg: rgba(255, 255, 255, 0.9);
    --input-bg: rgba(240, 240, 240, 0.9);
    --text-main: #1A1A1A;
    --text-subtle: #666666;
    --border-color: rgba(200, 200, 200, 0.4);
    --accent-color: #555555;
    --selected-color: #333333;
    --font-english: "Great Vibes", cursive;
    --font-main: "Haishui", var(--font-english);
    --font-quote: "LingDong", var(--font-english);
    --font-code: "Hangeuljaemin4.0", monospace;
    --font-title: "JasonHandwriting1", var(--font-english);
    --border-radius: 12px;
}

/* --- 3. 全局样式 (无阴影、无边框) --- */
* { box-shadow: none !important; border-style: none !important; }
body { background-color: var(--theme-bg) !important; color: var(--text-main); font-family: var(--font-main); }
#sheld, #character_view { background: transparent !important; margin: 0 auto !important; left: 0; right: 0; border: none !important; overflow: visible !important; }
#chat { background: transparent !important; align-items: center !important; padding-bottom: 120px !important; }
h1, h2, h3, h4, .standoutHeader, .inline-drawer-header, .title_restorable { font-family: var(--font-title); color: var(--text-main); }

/* --- 4. 顶部导航栏 & 挂件 --- */
#top-settings-holder { position:relative; background-color: var(--panel-bg-color); backdrop-filter: blur(8px); border: none; }
#top-settings-holder::after { content: ''; display: block; width: 80px; height: 100px; background-image: url('https://tc-new.z.wiki/autoupload/1N2_UJVYUo2KjM-_22IFnCfNcKcqEnRmcljopnyJoMs/20260226/NWmI/1229X1607/2026-02-26_112202.png/webp'); filter: grayscale(100%); background-size: contain; background-repeat: no-repeat; position: absolute; bottom: -85px; left: 20px; pointer-events: none; z-index: 100; }

.drawer-icon.fa-fw::before { content: '' !important; font-size: 0 !important; }
.drawer-icon.fa-fw { width: 35px; height: 40px; background-size: contain; background-repeat: no-repeat; background-position: center; transition: transform 0.3s ease; filter: grayscale(100%); }
.drawer-icon.fa-fw:hover { transform: scale(1.1); }

/* 自定义导航栏图标 */
.drawer-icon.fa-sliders, #ai-config-button .drawer-icon, .drawer-icon.fa-font, #advanced-formatting-button .drawer-icon, .drawer-icon.fa-user, #user-settings-button .drawer-icon, .drawer-icon.fa-cubes, #extensions-settings-button .drawer-icon, .drawer-icon.fa-address-card, #character_popup_button .drawer-icon {
    background-image: url('https://tc-new.z.wiki/autoupload/1N2_UJVYUo2KjM-_22IFnCfNcKcqEnRmcljopnyJoMs/20260226/qr2z/1518X1531/2026-02-26_203831.png/webp');
}
.drawer-icon.fa-plug, #sys-settings-button .drawer-icon, .drawer-icon.fa-book-atlas, #WI-SP-button .drawer-icon, .drawer-icon.fa-image, .drawer-icon.fa-panorama, .drawer-icon.fa-bars-progress, #table_database_settings_drawer .drawer-icon, .drawer-icon.fa-face-smile, #persona-management-button .drawer-icon {
    background-image: url('https://tc-new.z.wiki/autoupload/1N2_UJVYUo2KjM-_22IFnCfNcKcqEnRmcljopnyJoMs/20260226/9o08/1498X1493/2026-02-26_203859.png/webp');
}

.drawer-content { background-image: url('https://tc-new.z.wiki/autoupload/1N2_UJVYUo2KjM-_22IFnCfNcKcqEnRmcljopnyJoMs/20260226/eyLv/1200X757/c0e76dfcd1b9c451f875151f9c3d665b.jpg/webp'); background-size: cover; background-position: center; border: none !important; border-radius: var(--border-radius); }

/* --- 5. 底部悬浮输入栏 --- */
#send_textarea::placeholder { color: transparent !important; opacity: 0 !important; }
#send_textarea::-webkit-input-placeholder { color: transparent !important; opacity: 0 !important; }
#form_sheld { position: absolute !important; bottom: 15px !important; left: 0; right: 0; display: flex; justify-content: center; z-index: 1000; pointer-events: none; }
#send_form { pointer-events: auto; width: 90% !important; max-width: 800px !important; margin: 0 auto !important; border-radius: 25px !important; background-color: var(--input-bg) !important; padding: 10px 15px !important; backdrop-filter: blur(10px) !important; -webkit-backdrop-filter: blur(10px) !important; border: 1px solid rgba(200,200,200,0.2) !important; transition: all 0.5s ease !important; position: relative; }
#send_form:hover { transform: translateY(-5px) !important; background-color: var(--panel-bg-hover) !important; border: 1px solid var(--accent-color) !important; }
#rightSendForm, #leftSendForm { gap: 10px; }
#send_textarea { clip-path: none !important; border: none !important; background: transparent !important; color: var(--text-main) !important; }
#nonQRFormItems:has(#send_textarea:placeholder-shown)::before { content: "寒风拂过冰原，留痕..."; color: var(--text-subtle); position: absolute; top: 50%; left: 50%; transform: translate(-50%, -50%); font-family: var(--font-main); font-size: 0.5em; pointer-events: none; z-index: 10; white-space: nowrap; }
#options_button::before, #send_but::before, #send_form #extensionsMenuButton::before, #ai_retry_button::before, #auto_completion_button::before { display: none !important; }
#options_button, #send_but, #send_form #extensionsMenuButton, #ai_retry_button, #auto_completion_button { width: 32px; height: 32px; background-size: contain; background-repeat: no-repeat; background-position: center; transition: transform 0.2s ease; font-size: 0; border: none; background-color: transparent; filter: grayscale(100%); }
#options_button:hover, #send_but:hover, #send_form #extensionsMenuButton:hover, #ai_retry_button:hover, #auto_completion_button:hover { transform: scale(1.1); }
#options_button, #ai_retry_button { background-image: url('https://tc-new.z.wiki/autoupload/1N2_UJVYUo2KjM-_22IFnCfNcKcqEnRmcljopnyJoMs/20260226/x3qr/1107X1519/2026-02-26_112246.png/webp'); }
#send_form #extensionsMenuButton { background-image: url('https://tc-new.z.wiki/autoupload/1N2_UJVYUo2KjM-_22IFnCfNcKcqEnRmcljopnyJoMs/20260226/fd3r/1573X1138/2026-02-26_112336.png/webp'); }
#send_but { background-image: url('https://tc-new.z.wiki/autoupload/1N2_UJVYUo2KjM-_22IFnCfNcKcqEnRmcljopnyJoMs/20260226/Fd0t/1722X1617/2026-02-26_113506.png/webp'); }
#auto_completion_button { background-image: url('https://tc-new.z.wiki/autoupload/1N2_UJVYUo2KjM-_22IFnCfNcKcqEnRmcljopnyJoMs/20260226/7DIP/1467X1509/2026-02-26_112312.png/webp'); }

/* --- 6. 核心：消息布局与样式 --- */
.mes { display: flex; flex-direction: column; padding: 0 !important; margin: 45px auto 40px !important; width: 85%; max-width: 700px; background: transparent !important; border: none !important; overflow: visible !important; position: relative; }
.mes .mesAvatarWrapper {
    display: flex; justify-content: center; align-items: center; padding: 0;
    border-radius: var(--border-radius) var(--border-radius) 0 0;
    width: 100%;
    background-size: cover; background-position: center;
    position: relative; z-index: 5;
    height: 180px !important; 
    min-height: 180px !important;
    overflow: visible !important;
}
.mes[is_user="true"] .mesAvatarWrapper { background-image: url('https://tc-new.z.wiki/autoupload/1N2_UJVYUo2KjM-_22IFnCfNcKcqEnRmcljopnyJoMs/20260226/K7iR/4578X2298/2026-02-26_185631.jpg/webp'); }
.mes[is_user="false"] .mesAvatarWrapper { background-image: url('https://tc-new.z.wiki/autoupload/1N2_UJVYUo2KjM-_22IFnCfNcKcqEnRmcljopnyJoMs/20260226/DRxn/4578X2298/2026-02-26_185837.jpg/webp'); }
.mes .avatar {
    position: absolute;
    top: 50%; left: 50%;
    transform: translate(-50%, -50%);
    width: 155px; height: 215px; 
    background-color: #FAFAFA !important;
    padding: 8px 8px 26px 8px !important; 
    border: 1px solid rgba(0,0,0,0.05) !important;
    z-index: 10;
    display: flex !important; 
    align-items: center;
    justify-content: center;
    border-radius: 2px !important;
}
.mes .avatar img {
    width: 100% !important; height: 100% !important;
    object-fit: cover !important; 
    border-radius: 0 !important; border: none !important;
    image-rendering: -webkit-optimize-contrast; 
    image-rendering: crisp-edges;
    filter: grayscale(10%);
}
.mes .mesAvatarWrapper::after { 
    content: '';
    position: absolute;
    left: 50%; transform: translateX(-50%);
    z-index: 15;
    background-image: url('https://tc-new.z.wiki/autoupload/1N2_UJVYUo2KjM-_22IFnCfNcKcqEnRmcljopnyJoMs/20260226/l2zo/4578X2298/2026-02-26_114326.png/webp');
    filter: grayscale(100%) opacity(0.8);
    background-size: contain; 
    background-repeat: no-repeat;
    background-position: center;
    bottom: -35px; 
    width: 330px; 
    height: 60px; 
}
.mes .mes_block {
    background-color: transparent !important; 
    background-image: 
        linear-gradient(to bottom, #ffffff 0%, rgba(255, 255, 255, 0.95) calc(100% - 150px), rgba(255, 255, 255, 0.6) 100%), 
        url('https://tc-new.z.wiki/autoupload/1N2_UJVYUo2KjM-_22IFnCfNcKcqEnRmcljopnyJoMs/20260226/oz0u/2160X2400/2026-02-26_204947.jpg/webp');
    background-size: 100% 100%, 100% auto !important;
    background-position: center top, center bottom !important; 
    background-repeat: no-repeat !important; 
    border-radius: 0 0 var(--border-radius) var(--border-radius);
    padding: 80px 30px 45px !important; 
    margin-top: 0 !important; 
    position: relative;
    border: none !important;
    overflow: visible !important; 
    min-height: 150px !important; 
}

.mes .mes_text, .mes_reasoning { background: transparent !important; border: none !important; padding: 0 !important; margin: 0 !important; backdrop-filter: none !important; }
#chat .mes .mes_reasoning_header { background: transparent !important; border: none !important; border-radius: 0; backdrop-filter: none !important; padding: 0 !important; margin-bottom: 10px !important; display: inline-flex !important; align-items: center !important; }
.mes_reasoning_arrow { display: none !important; }
.mes_reasoning_header h4, .mes_reasoning_header_title { font-size: 0 !important; visibility: hidden; }
.mes_reasoning_header h4::before, .mes_reasoning_header_title::before { content: "冰雪消融，思绪沉淀"; font-family: var(--font-title); font-size: 14px !important; color: var(--accent-color); visibility: visible; }
.mes_reasoning { border-left: 2px solid #888 !important; padding-left: 15px !important; margin-bottom: 20px !important; color: var(--text-subtle); }
.mes .mes_text { line-height: 1.9; color: var(--text-main); }

/* --- 黑白极简排版与文字特效系统 --- */
.mes_text h1 {
    font-family: var(--font-title);
    color: var(--text-main);
    font-size: 1.6em;
    text-align: center;
    position: relative;
    padding-bottom: 12px;
    margin: 30px 0 20px 0;
    border-bottom: 1px solid #CCCCCC !important;
    font-weight: normal;
    letter-spacing: 2px;
}
.mes_text h1::after {
    content: '◆';
    position: absolute;
    bottom: -11px;
    left: 50%;
    transform: translateX(-50%);
    color: var(--accent-color);
    font-size: 12px;
    background: #ffffff; 
    padding: 0 12px;
}
.mes_text h2 {
    font-family: var(--font-title);
    color: var(--text-main);
    font-size: 1.3em;
    padding: 6px 0 6px 15px;
    border-left: 3px solid #555555 !important;
    margin: 25px 0 15px 0;
    background: linear-gradient(to right, rgba(0, 0, 0, 0.04) 0%, transparent 100%);
    border-radius: 0 8px 8px 0;
    font-weight: normal;
}
.mes_text em, .mes_text i {
    font-family: var(--font-quote);
    font-style: normal !important;
    color: var(--italics_text_color); 
    background: #F0F0F0; 
    padding: 2px 6px;
    border-radius: 4px;
    margin: 0 2px;
}
.mes_text strong, .mes_text b {
    font-family: var(--font-title);
    color: #000000;
    font-weight: bold;
    border-bottom: 1px dashed #666666 !important;
    padding: 0 2px;
}
.mes_text blockquote {
    background-color: #F8F8F8;
    border: none !important;
    border-left: 3px solid #444444 !important;
    padding: 12px 18px;
    border-radius: 0 8px 8px 0;
    margin: 18px 0;
    font-family: var(--font-quote);
    color: var(--quote_text_color);
    position: relative;
}
.mes_text span.quote, .mes_text q, .mes_text .dialogue {
    font-family: var(--font-quote);
    color: var(--quote_text_color);
}
.mes_text code { font-family: var(--font-code); background-color: #E8E8E8 !important; color: var(--text-main) !important; padding: 2px 6px; border-radius: 4px; border: none !important; }

/* 侧边装饰（黑白化处理） */
.mes[is_user="false"] .mes_block::before {
    content: ''; display: block; position: absolute;
    top: -10px; left: -30px; 
    width: 100px; height: 65px;
    background-image: url('https://tc-new.z.wiki/autoupload/1N2_UJVYUo2KjM-_22IFnCfNcKcqEnRmcljopnyJoMs/20260226/U4Mz/2048X2048/2026-02-26_114127.png/webp');
    filter: grayscale(100%) opacity(0.7);
    background-size: contain; background-repeat: no-repeat; pointer-events: none; z-index: 20;
    transform: scaleX(-1) rotate(-15deg); 
}
.mes[is_user="true"] .mes_block::after {
    content: ''; display: block; position: absolute;
    bottom: -30px; right: -25px; 
    width: 75px; height: 95px;
    background-image: url('https://tc-new.z.wiki/autoupload/1N2_UJVYUo2KjM-_22IFnCfNcKcqEnRmcljopnyJoMs/20260226/jlby/1326X1736/2026-02-26_112425.png/webp');
    filter: grayscale(100%) opacity(0.7);
    background-size: contain; background-repeat: no-repeat; pointer-events: none; z-index: 20;
    transform: rotate(-10deg);
}

/* --- 楼层信息、时间戳与编辑按钮 --- */
.mes .mesAvatarWrapper > .ch_name { display: none !important; }
.mes .mes_block > .ch_name {
    display: flex !important; 
    position: absolute;
    top: 25px !important;
    left: 30px !important;
    right: 30px !important;
    width: auto !important;
    justify-content: space-between !important; 
    align-items: flex-start !important;        
    background: transparent !important;
    border: none !important;
    z-index: 100; 
    transform: none !important;
    padding: 0;
}
.mes .ch_name > .flex-container {
    display: flex !important;
    align-items: center !important;
    gap: 10px !important;
    flex-wrap: wrap !important;
}
.mes .ch_name .name_text { font-weight: bold; font-size: 13px !important; color: var(--text-main) !important; }
.mes .mesIDDisplay, .mes .mes_timer {
    position: static !important; 
    color: var(--text-subtle) !important; 
    font-size: 12px !important; 
    line-height: 1 !important;
    transform: none !important;
}
.mes .mesIDDisplay { font-family: var(--font-title); }

/* 悬浮侧边工具栏 */
.mes .mes_buttons, .mes .mes_edit_buttons {
    flex-direction: row-reverse;
    gap: 8px;
    position: static !important;
    opacity: 0.65;              
    transition: opacity 0.3s ease;
    pointer-events: auto !important;
}
.mes:hover .mes_buttons, .mes:hover .mes_edit_buttons { opacity: 1; }
.mes .mes_buttons .mes_button, .mes .mes_edit_buttons .mes_button {
    background-color: rgba(238, 238, 238, 0.7) !important;
    backdrop-filter: blur(4px);
    color: var(--text-subtle) !important;
    padding: 6px !important;
    border-radius: 6px !important;
    cursor: pointer;
    transition: all 0.2s ease;
    font-size: 14px !important;
    height: auto !important;
    width: auto !important;
    line-height: 1 !important;
    border: none !important;
}
.mes .mes_buttons .mes_button:hover, .mes .mes_edit_buttons .mes_button:hover {
    background-color: var(--accent-color) !important;
    color: white !important;
    transform: scale(1.1);
}

/* 打字提示器 */
#typing_indicator { background-image: url('https://tc-new.z.wiki/autoupload/1N2_UJVYUo2KjM-_22IFnCfNcKcqEnRmcljopnyJoMs/20260226/fd3r/1573X1138/2026-02-26_112336.png/webp') !important; background-size: contain !important; background-repeat: no-repeat !important; background-position: center !important; filter: grayscale(100%); animation: pulse 1.5s infinite ease-in-out; border: none !important; height: 40px !important; width: 40px !important; margin: 10px auto !important; }
#typing_indicator .dot { display: none !important; }
@keyframes pulse { 0% { transform: scale(0.95); opacity: 0.7; } 50% { transform: scale(1.05); opacity: 1; } 100% { transform: scale(0.95); opacity: 0.7; } }

/* --- 全局UI无边框设定 --- */
.standoutHeader, .inline-drawer-header, .title_restorable, #extensions_settings2 > div, #extensions_settings > div, .openai_logit_bias_preset_form, details > summary, #power-user-options-block h4, #InstructSettingsColumn h4, #SystemPromptColumn h4, #ContextSettings h4, .persona_management_global_settings h4, #character_popup h4, #AdvancedFormatting h4, #rm_group_chats_block h4, div[name*='HandlingToggles'] h4, div[name*='MiscellaneousToggles'] h4 { background: var(--card-bg) !important; border: none !important; border-radius: 8px !important; padding: 8px 12px !important; margin-bottom: 8px !important; color: var(--text-main) !important; }
input[type="text"], input[type="number"], input[type="search"], textarea, select, .text_pole { background-color: var(--input-bg) !important; border: none !important; color: var(--text-main) !important; border-radius: 6px !important; padding: 8px !important; }
input:focus, textarea:focus, select:focus { outline: 1px solid var(--accent-color) !important; }
.menu_button { background-color: var(--card-bg) !important; border: none !important; color: var(--text-main) !important; transition: all 0.2s ease; border-radius: 6px !important; }
.menu_button:hover { background-color: var(--accent-color) !important; color: white !important; }
input[type="checkbox"]:checked::before { box-shadow: inset 1em 1em var(--accent-color) !important; }

/* 弹窗设计 */
dialog.popup { background-color: transparent !important; border: none !important; }
dialog.popup .popup-body, #dialogue_popup { background-image: url('https://tc-new.z.wiki/autoupload/1N2_UJVYUo2KjM-_22IFnCfNcKcqEnRmcljopnyJoMs/20260226/eyLv/1200X757/c0e76dfcd1b9c451f875151f9c3d665b.jpg/webp') !important; background-size: cover !important; background-position: center !important; border: none !important; border-radius: var(--border-radius) !important; position: relative; overflow: hidden; }
dialog.popup .popup-body::before, #dialogue_popup::before { content: ''; position: absolute; top: 0; left: 0; right: 0; bottom: 0; background-color: rgba(255, 255, 255, 0.85); backdrop-filter: blur(5px); z-index: 0; }
dialog.popup .popup-body > *, #dialogue_popup > * { position: relative; z-index: 1; }
.menu_button.active, .menu_button.world_set, .menu_button.fav_on { background-color: var(--selected-color) !important; color: #fff !important; font-weight: bold; }
#left-nav-panel .menu_button.selected { background-color: var(--selected-color) !important; color: #fff !important; }

/* 滑块设计 */
input[type="range"]::-webkit-slider-thumb { -webkit-appearance: none !important; appearance: none !important; width: 28px !important; height: 28px !important; background-image: url('https://tc-new.z.wiki/autoupload/1N2_UJVYUo2KjM-_22IFnCfNcKcqEnRmcljopnyJoMs/20260226/6NE0/1237X1522/2026-02-26_112148.png/webp') !important; filter: grayscale(100%); background-size: contain !important; background-repeat: no-repeat !important; background-position: center !important; background-color: transparent !important; border: none !important; cursor: pointer !important; }
input[type="range"]::-moz-range-thumb { width: 28px !important; height: 28px !important; background-image: url('https://tc-new.z.wiki/autoupload/1N2_UJVYUo2KjM-_22IFnCfNcKcqEnRmcljopnyJoMs/20260226/6NE0/1237X1522/2026-02-26_112148.png/webp') !important; filter: grayscale(100%); background-size: contain !important; background-repeat: no-repeat !important; background-position: center !important; background-color: transparent !important; border: none !important; cursor: pointer !important; }
.neo-range-slider { background: rgba(150, 150, 150, 0.3) !important; }

/* --- 楼层信息显示 --- */
.mes .mesIDDisplay {
    position: absolute;
    top: 192px !important; 
    background: rgba(255, 255, 255, 0.85) !important;
    border: none !important;
    color: var(--text-subtle) !important; 
    font-size: 12px !important; 
    backdrop-filter: blur(4px) !important;
    z-index: 100; 
    padding: 4px 10px !important;
